interface ExportRole { String export(); }
abstract class ProductBaseType {
    final String id;
    ProductBaseType(String id) { this.id = id; }
}
class OrthoRole extends ProductBaseType implements ExportRole {
    OrthoRole(String id) { super(id); }
    public String export() { return "csv:" + id; }
}
public class InterfaceOrClassDemo {
    public static void main(String[] args) { System.out.println(new OrthoRole("O1").export()); }
}
